using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEngine;
namespace AboutMe.Editor
{
    public static class PartyFieldTests
    {
        static readonly FieldInfo Cache=typeof(CampusGeometry).GetField("solids",BindingFlags.NonPublic|BindingFlags.Static);
        static CampusSolid[] Flat=>new[]{new CampusSolid{name="test_floor",center=new Vector3(0,-.5f,0),size=new Vector3(60,1,60)}};
        static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
        public static Match Make(string id)
        {
            var d=PartyMechanicRegistry.Find(id);var m=new Match("FIELDS",new MatchRules{revealDuration=.01f,handInterval=9999,finalTime=9999});
            for(int i=0;i<3;i++)m.Add(new Profile{playerId="p"+i,nickname="p"+i,appearance=AppearanceData.Demo(i),personas=Enumerable.Range(0,4).Select(n=>new PersonaAsset{assetId="p"+i+n,name=d.label,templateId="SpecialAbility",visualId=i==0?d.visualId:"book",color="#86ADCB"}).ToArray()});
            m.Phase=MatchPhase.Reveal;m.Tick(.02f);m.Time=10;m.Props.Clear();
            for(int i=0;i<3;i++){var p=m.Players["p"+i];p.position=new Vector3(i*10,1,0);p.motorHeight=1;p.input=new Command();p.lastInput=m.Time;p.yaw=0;}
            return m;
        }
        public static void Input(Match m,string id,string action="",float x=0,float z=0)
        {var p=m.Players[id];m.Receive(id,new Command{sequence=p.sequence+1,action=action,x=x,z=z,yaw=p.yaw});}
        public static void Tick(Match m,float seconds,string mover=null,float x=0,float z=0)
        {for(int i=0;i<Mathf.CeilToInt(seconds/.02f-.001f);i++){foreach(var p in m.Players.Values)Input(m,p.profile.playerId,"",p.profile.playerId==mover?x:0,p.profile.playerId==mover?z:0);m.Tick(.02f);}}
        public static EffectState Deploy(Match m)
        {Input(m,"p0","use_item");Tick(m,PartyMechanicRegistry.ForVisual(m.Item(m.Players["p0"].equipped).asset.visualId).windup+.02f);return m.Effects.Last(e=>e.kind=="PartyMechanic");}
        public static PersonaInstance Ground(Match m,Vector3 position)
        {var item=m.Items.First(x=>x.ownerId=="p2"&&x.state==ItemState.Inventory);item.state=ItemState.Ground;item.position=position;item.velocity=Vector3.zero;return item;}
        [MenuItem("About Me/Tests/Party fields authority")]
        public static void Run()
        {
            var old=Cache.GetValue(null);var failures=new List<string>();int passed=0;
            void Test(string name,Action run){Cache.SetValue(null,Flat);try{run();passed++;Debug.Log("PARTY_FIELD_PASS "+name);}catch(Exception e){failures.Add(name+": "+e.Message);Debug.LogError("PARTY_FIELD_FAIL "+name+": "+e);}}
            try
            {
                Test("wet footprints slow braking but jumping restores control",()=>{var m=Make("wet-trail");var e=Deploy(m);m.Players["p0"].position=new Vector3(-4,1,0);var b=m.Players["p1"];b.position=new Vector3(0,1,0);Tick(m,.16f,"p1",0,1);float before=b.position.z;Tick(m,.2f);Check(b.position.z>before+.08f&&b.fieldStatus.Contains("湿滑"),"no wet momentum");b.position.y=2;b.airborne=true;b.verticalSpeed=2;before=b.position.z;Tick(m,.08f);Check(Mathf.Abs(b.position.z-before)<.02f&&b.fieldStatus=="","airborne remained wet");});
                Test("trail points are public and bounded to six",()=>{var m=Make("wet-trail");var e=Deploy(m);Tick(m,2,"p0",0,1);Check(e.path.Length<=6&&e.path.Length>=3&&m.View("p1").effects.First(x=>x.id==e.id).path.Length==e.path.Length,"unbounded/private trail");});
                Test("sand slows by dwell time and resets upon leaving",()=>{var m=Make("sand-sink");var e=Deploy(m);var b=m.Players["p1"];b.position=e.position+Vector3.up*.85f;Tick(m,1.1f);Tick(m,.1f,"p1",1,0);Check(b.velocity.x<3&&b.velocity.x>0&&b.fieldStatus.Contains("浅沙"),"sand did not gradually slow");b.position=new Vector3(8,1,0);Tick(m,.02f);Check(!e.touchTimes.ContainsKey("p1"),"sand dwell persisted outside");});
                Test("sticky steps pause intermittently but do not lock jump",()=>{var m=Make("sticky-step");var e=Deploy(m);var b=m.Players["p1"];b.position=e.position+Vector3.up*.85f;Tick(m,.2f,"p1",1,0);Check(e.touchTimes.ContainsKey("p1hold"),"walking never triggered glue");Input(m,"p1","jump");Tick(m,.12f,"p1",1,0);Check(b.airborne&&b.fieldStatus=="","glue blocked jump");});
                Test("wind cone pushes front and loose objects without harming players",()=>{var m=Make("fan-volume");var e=Deploy(m);var b=m.Players["p1"];b.position=e.position+Vector3.up*.85f+Vector3.forward;var c=m.Players["p2"];c.position=e.position+Vector3.up*.85f+Vector3.right*2;var item=Ground(m,e.position+Vector3.up*.2f+Vector3.forward*2);var origin=item.position;float before=b.position.z;Tick(m,.3f);Check(b.position.z>before+.4f&&item.position.z>origin.z+.1f&&b.stability==100&&c.velocity.magnitude<.1f,"wind cone or damage wrong player="+b.position.z+" start="+before+" item="+item.position.z+" itemStart="+origin.z+" stability="+b.stability+" sideVel="+c.velocity);});
                Test("wall blocks wind and magnetic pull",()=>{foreach(var id in new[]{"fan-volume","tractor-loose"}){var m=Make(id);var e=Deploy(m);var item=Ground(m,e.position+Vector3.up*.2f+Vector3.forward*2);var before=item.position;Cache.SetValue(null,Flat.Concat(new[]{new CampusSolid{name="wall",center=e.position+Vector3.up*.85f+Vector3.forward,size=new Vector3(4,2,.2f)}}).ToArray());Tick(m,.3f);Check(FlatDistance(item.position,before)<.01f,"field crossed wall: "+id);}});
                Test("whirlpool rotates only ground assets and public loose props",()=>{var m=Make("loose-whirlpool");var e=Deploy(m);var item=Ground(m,e.position+Vector3.up*.2f+Vector3.right*2);var prop=new PublicProp{id="crate",visual="box",position=e.position+Vector3.up*.45f+Vector3.left*2};m.Props.Add(prop);var b=m.Players["p1"];b.position=e.position+Vector3.up*.85f+Vector3.forward;var before=b.position;Tick(m,.4f);Check(Mathf.Abs(item.position.z-e.position.z)>.2f&&Mathf.Abs(prop.position.z-e.position.z)>.2f&&FlatDistance(b.position,before)<.01f,"whirlpool target class wrong item="+item.position+" prop="+prop.position+" player="+b.position+" center="+e.position);Check(item.ownerId=="p2"&&item.state==ItemState.Ground,"whirlpool stole asset");});
                Test("magnet pulls then stops near center without recovering; carried assets excluded",()=>{var m=Make("tractor-loose");var e=Deploy(m);var item=Ground(m,e.position+Vector3.up*.2f+Vector3.right*2.5f);Tick(m,1.5f);Check(FlatDistance(item.position,e.position)<1.1f&&item.state==ItemState.Ground&&item.ownerId=="p2","magnet did not pull or auto recovered item="+item.position+" center="+e.position+" state="+item.state);item.state=ItemState.Carried;item.carrierId="p1";item.position=new Vector3(9,.35f,0);item.velocity=Vector3.zero;Tick(m,.2f);Check(item.position.x==9,"magnet moved carried asset");});
                Test("public repel warns then pushes selected prop; grabbing cancels",()=>{foreach(bool held in new[]{false,true}){var m=Make("polarity-push");var prop=new PublicProp{id="crate",visual="box",position=new Vector3(0,.6f,4)};m.Props.Add(prop);var e=Deploy(m);Check(e.stage=="repel_warning"&&prop.velocity.magnitude<.1f,"repel skipped warning");if(held){prop.holder="p1";m.Players["p1"].publicProp=prop.id;}Tick(m,.55f);Check(held?!m.Effects.Contains(e):prop.position.z>4.2f,"repel/counter failed");}});
                Test("low wave hits ground once and ignores airborne assets and players",()=>{var m=Make("item-push-wave");var item=Ground(m,new Vector3(2,.35f,0));var higher=m.Items.First(x=>x.ownerId=="p1"&&x.state==ItemState.Inventory);higher.state=ItemState.Ground;higher.position=new Vector3(-2,12,0);higher.velocity=Vector3.zero;m.Players["p1"].position=new Vector3(0,1,2);var e=Deploy(m);Tick(m,.5f);Check(item.position.x>2.2f&&e.hit.Count(x=>x==item.id)==1&&higher.position.x==-2&&m.Players["p1"].stability==100&&m.Players["p1"].velocity.magnitude<.1f,"wave class/height or repeat failure item="+item.position+" hits="+string.Join(",",e.hit)+" upper="+higher.position+" b="+m.Players["p1"].velocity);});
                Test("rain clears glue and attached sticker but conserves original Persona",()=>{var m=Make("clean-rain");var source=m.Item(m.Players["p2"].equipped);var glue=new EffectState{id="glue",kind="PartyMechanic",mechanicId="sticky-step",sourceInstance=source.id,owner="p2",position=new Vector3(0,.15f,2),deadline=m.Time+5,radius=2};var sticker=new EffectState{id="sticker",kind="PartyMechanic",mechanicId="sticky-burst",sourceInstance=source.id,owner="p2",stage="attached",targetId="p1",position=new Vector3(0,1,2),deadline=m.Time+5};m.Players["p1"].position=new Vector3(0,1,2);m.Effects.Add(glue);m.Effects.Add(sticker);Deploy(m);Check(!m.Effects.Contains(glue)&&!m.Effects.Contains(sticker)&&source.state==ItemState.Equipped&&m.Remaining("p2")==4,"rain deleted life or did not clean");});
                Test("fire hits twice, pushes once, side is safe and immunity respected",()=>{var m=Make("flame-fan");var b=m.Players["p1"];b.position=new Vector3(0,1,2);m.Players["p2"].position=new Vector3(2,1,0);var e=Deploy(m);Tick(m,.8f);Check(b.stability==76&&m.Players["p2"].stability==100&&m.CombatEvents.Count(x=>x.kind=="party_flame")==2,"fire pulse count or cone wrong");Check(e.hit.Count==1,"fire repeated push mark count="+e.hit.Count+" ids="+string.Join(",",e.hit));var n=Make("flame-fan");n.Players["p1"].position=new Vector3(0,1,2);n.Players["p1"].bodyProtectedUntil=n.Time+5;Deploy(n);Tick(n,.8f);Check(n.Players["p1"].stability==100,"fire bypassed immunity");});
                Test("fire respects walls and depleted victim drops only one life",()=>{var m=Make("flame-fan");m.Players["p1"].position=new Vector3(0,1,2);Cache.SetValue(null,Flat.Concat(new[]{new CampusSolid{name="wall",center=new Vector3(0,1,1),size=new Vector3(3,2,.2f)}}).ToArray());Deploy(m);Tick(m,.8f);Check(m.Players["p1"].stability==100,"fire crossed wall");Cache.SetValue(null,Flat);var n=Make("flame-fan");n.Players["p1"].position=new Vector3(0,1,2);n.Players["p1"].stability=1;n.Players["p1"].lastHit=n.Time;Deploy(n);Tick(n,.8f);Check(n.Items.Count(x=>x.ownerId=="p1"&&x.state==ItemState.Ground)==1&&n.Remaining("p1")==4,"fire duplicated Persona drop");});
                Test("field budget rejects ninth deployed device without spending cooldown",()=>{var m=Make("sand-sink");for(int i=0;i<8;i++)m.Effects.Add(new EffectState{id="old"+i,kind="PartyMechanic",mechanicId="fan-volume",owner="p0",sourceInstance=m.Players["p0"].equipped,position=new Vector3(-20,.15f,i),deadline=m.Time+5,radius=5});Input(m,"p0","use_item");Tick(m,.35f);Check(m.Effects.Count==8&&m.View("p0").players.First(x=>x.id=="p0").mechanicCooldown<1,"budget overflow or spent cooldown");});
                Test("room effect cap rejects three-part cluster without duplicating lives",()=>{var m=Make("cluster-burst");for(int i=0;i<23;i++)m.Effects.Add(new EffectState{id="old"+i,kind="PartyMechanic",mechanicId="item-push-wave",sourceInstance=m.Players["p1"].equipped,owner="p1",stage="loose_wave",position=new Vector3(-20,.15f,i),createdAt=m.Time,deadline=m.Time+5});Input(m,"p0","use_item");Tick(m,.4f);Check(m.Effects.Count==23&&m.Remaining("p0")==4,"effect cap overflow");});
                Test("remote detonation remains available at full device budget",()=>{var m=Make("remote-burst");var remote=Deploy(m);for(int i=0;i<7;i++)m.Effects.Add(new EffectState{id="old"+i,kind="PartyMechanic",mechanicId="fan-volume",owner="p1",sourceInstance=m.Players["p1"].equipped,stage="field",position=new Vector3(-20,.15f,i),deadline=m.Time+5,radius=5});Tick(m,.5f);Input(m,"p0","use_item");Tick(m,.25f);Check(remote.stage=="burst","device budget blocked existing remote detonation");});
                Test("finish consume and cancel remove proper fields without extra lives",()=>{foreach(var id in new[]{"wet-trail","sand-sink","fan-volume","loose-whirlpool","tractor-loose","flame-fan"}){var m=Make(id);var e=Deploy(m);m.Item(e.sourceInstance).state=ItemState.Consumed;Tick(m,.02f);Check(!m.Effects.Contains(e)&&m.Remaining("p0")==3,"consume cleanup/life failure");var n=Make(id);Deploy(n);n.Finish("timeout");Check(!n.Effects.Any(x=>x.kind=="PartyMechanic"),"finish retained fields");}var self=Make("wet-trail");Deploy(self);Input(self,"p0","cancel");Check(self.Effects.Count==0,"Q did not stop self emitter");});
            }
            finally{Cache.SetValue(null,old);}
            if(failures.Count>0)throw new Exception(string.Join("\n",failures));Debug.Log("PARTY_FIELDS_PASSED "+passed+" authority scenarios / ten distinct fields");
        }
        static float FlatDistance(Vector3 a,Vector3 b){a.y=b.y=0;return Vector3.Distance(a,b);}
    }
}
